function validate([cards]) {
  if (!Array.isArray(cards) || cards.length < 1 || cards.length > 100000) return 'cards needs 1 to 10^5 values.';
  if (cards.some(v => !Number.isInteger(v) || v < 0 || v > 1000000)) return 'Each card is an integer from 0 to 10^6.';
  return null;
}

