function minimumCardPickup(cards) {
  const lastSeen = new Map();
  let best = Infinity;

  for (let i = 0; i < cards.length; i++) {
    const card = cards[i];
    if (lastSeen.has(card)) {
      best = Math.min(best, i - lastSeen.get(card) + 1);
    }
    lastSeen.set(card, i);
  }

  return best === Infinity ? -1 : best;
}

