function minimumCardPickup(cards) {
  // Try every pair of equal cards and keep the shortest span between them.
  let answer = -1;
  for (let i = 0; i < cards.length; i++)
    for (let j = i + 1; j < cards.length; j++)
      if (cards[i] === cards[j] && (answer === -1 || j - i + 1 < answer)) answer = j - i + 1;
  return answer;
}

