function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') {
    const n = 2000;
    const mode = pick(3);
    if (mode === 0) {
      // All distinct: the answer is -1.
      const cards = Array.from({ length: n }, (_, i) => i * 499);
      for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [cards[i], cards[j]] = [cards[j], cards[i]]; }
      return [cards];
    }
    const span = mode === 1 ? 1000001 : 900;
    return [Array.from({ length: n }, () => pick(span))];
  }
  const n = 1 + pick(10);
  const span = 1 + pick(8);
  const big = rand() < 0.2;
  return [Array.from({ length: n }, () => big ? 1000000 - pick(span) : pick(span))];
}
